-- ViewRepository.getUniqueOriginalPaths
select distinct
  substring("asset"."originalPath", $1) as "directoryPath"
from
  "asset"
where
  "ownerId" = $2::uuid
  and (
    "asset"."visibility" in ('timeline')
    and (
      coalesce("asset"."hiddenFrom", 0) | (
        coalesce("asset"."hiddenFromInherited", 0) & ~ coalesce("asset"."hiddenFromShown", 0)
      )
    ) & 2048 = 0
  )
  and "deletedAt" is null
  and "fileCreatedAt" is not null
  and "fileModifiedAt" is not null
  and "localDateTime" is not null
order by
  "directoryPath" asc

